<template><div class="brand-page"><section class="page-hero"><div class="site-shell"><span class="eyebrow">APIMTC</span><h1>{{data.title}}</h1><p>{{data.lead}}</p></div></section><section class="section"><div class="site-shell"><div class="section-heading"><span class="eyebrow">{{data.kicker}}</span><h2>{{data.heading}}</h2></div><div class="content-grid"><article v-for="item in data.items" :key="item.title" class="info-block"><span class="block-number">{{item.num}}</span><h3>{{item.title}}</h3><p>{{item.text}}</p></article></div></div></section><section class="section dark-section"><div class="site-shell split"><div><span class="eyebrow">{{tx('OUR PURPOSE','我们的使命')}}</span><h2>{{tx('Connecting people, places, education, industry and opportunity.','连接人才、城市、教育、产业与机会。')}}</h2></div><router-link class="button button-light" to="/contact">{{tx('Start a conversation','开始洽谈')}}</router-link></div></section></div></template>
<script setup lang="ts">import {computed} from 'vue';import {useRoute} from 'vue-router';import {useI18n} from '@/composables/useI18n';const route=useRoute();const {lang}=useI18n();const tx=(en:string,zh:string)=>lang.value==='en'?en:zh;const sets:any={about:{title:'About APIMTC',lead:'Connecting people. Connecting worlds.',kicker:'OUR STORY',heading:'Singapore is our home.',items:[['01','From MICE & travel to education & mobility','Our experience has evolved into a broader international platform connecting education, skills, people, industry and business.'],['02','Our brand structure','APIMTC Singapore is our parent company and international platform. API EduVoyage Chengdu is our China education mobility platform.'],['03','Two-way international connections','Singapore → China and the world. China and the world → Singapore. Meaningful exchange in both directions.']]},mobility:{title:'Education Mobility',lead:'Beyond borders. Beyond the classroom.',kicker:'THE 4E MODEL',heading:'Learn. Experience. Explore. Exchange.',items:[['01','Singapore Future Explorers','Discover Singapore through life and health, space and aviation, sustainability, AI and emerging industries.'],['02','China Beyond the Classroom','Experience China\'s universities, technology, innovation, smart cities and culture.'],['03','Designed for every age','Primary, junior high and senior high programmes shaped around age, learning objectives and school needs.']]},'mice-business':{title:'MICE & Business',lead:'Connecting business with experience.',kicker:'WHAT WE DO',heading:'Professional experiences with purpose.',items:[['01','MICE','Meetings, incentives, conferences and events across Singapore, China and international destinations.'],['02','Professional learning','Executive programmes, business delegations, industry visits, benchmarking and business exchange.'],['03','End-to-end delivery','Destination expertise, international networks and professional programme execution.']]},partnerships:{title:'International Partnerships',lead:'Build international programmes together.',kicker:'WHO WE PARTNER WITH',heading:'From idea to delivery.',items:[['01','Schools and universities','International learning, student mobility, academic collaboration and exchange.'],['02','Governments and organisations','Delegations, benchmarking and purposeful international exchange.'],['03','Companies and industry','Professional learning, innovation, talent development and real-world engagement.']]},'china-gateway':{title:'Chengdu · Connecting China',lead:'API EduVoyage · Our China gateway.',kicker:'CHINA GATEWAY',heading:'China beyond the destination.',items:[['01','API EduVoyage','APIMTC’s Chengdu-based education mobility platform connecting education, skills, student mobility and institutional exchange.'],['02','Singapore → Chengdu → China → The World','We connect Singapore’s international perspective with China’s education, industry and innovation ecosystems.'],['03','Every city is a classroom','Shanghai · Shenzhen · Hangzhou · Suzhou · Beijing · Xi’an · Chengdu · Guangzhou.']]} };const data=computed(()=>{const key=route.path.slice(1)||'about';const s=sets[key]||sets.about;return {...s,items:s.items.map((x:string[])=>({num:x[0],title:tx(x[1],x[1]),text:tx(x[2],x[2])}))}})</script>
